gth": 128,          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$"        },        "turn_id": {          "type": "string",          "minLength": 1,          "maxLength": 128,          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$"        },        "session_id": {          "type": "string",          "minLength": 1,          "maxLength": 128,          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$"        },        "invocation_id": {          "type": "string",          "minLength": 1,          "maxLength": 128,          "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$"        },        "result_digest": {          "type": "string",          "pattern": "^sha256:[0-9a-f]{64}$"        },        "revision": {          "type": "integer",          "minimum": 1        },        "conversation_revision": {          "type": "integer",          "minimum": 1        },        "request_digest": {          "type": "string",          "pattern": "^sha256:[0-9a-f]{64}$"        },        "context_revision": {          "type": "string",          "pattern": "^sha256:[0-9a-f]{64}$"        }      }    }  },  "anyOf": [    {      "$ref": "#/$defs/capability"    },    {      "$ref": "#/$defs/selection"    },    {      "$ref": "#/$defs/prepared"    },    {      "$ref": "#/$defs/request"    },    {      "$ref": "#/$defs/operation"    },    {      "$ref": "#/$defs/error"    }  ]}"###.utf8)
    static func validate(_ value: Any, kind: String) throws {
        let schema = try JSONSerialization.jsonObject(with: schemaData) as! [String: Any]
        let definitions = schema["$defs"] as! [String: Any]
        try AdvisoryWire.check(value, definitions[kind] as! [String: Any], definitions: definitions)
    }
}

extension WorksetReleaseWire {
    static func object(_ data: Data) throws -> [String: Any] {
        guard data.count <= 1_000_000, let raw = try JSONSerialization.jsonObject(with: data) as? [String: Any] else { throw AdvisoryError.invalid }
        return raw
    }
    static func require(_ condition: Bool) throws {
        guard condition else { throw AdvisoryError.invalid }
    }
    static func scope(_ raw: [String: Any], access: WorksetReleaseAccess) throws {
        guard raw["instance_id"] as? String == access.forgeInstanceID,
              raw["project_id"] as? String == access.forgeProjectID,
              raw["repository_id"] as? String == access.repositoryID else { throw AdvisoryError.denied }
    }
    static func capability(_ data: Data, access: WorksetReleaseAccess, now: Date = Date()) throws -> WorksetReleaseCapability {
        let raw = try object(data); try validate(raw, kind: "capability")
        let cap = try AdvisoryWire.decode(raw, as: WorksetReleaseCapability.self)
        try scope(raw["scope"] as! [String: Any], access: access)
        guard cap.principal_id == access.actorID, cap.subjects == access.subjects,
              Set(cap.permissions).count == cap.permissions.count, cap.permissions.contains("READ"),
              !cap.release_supported || cap.permissions.contains("RELEASE"),
              !cap.disarm_supported || cap.permissions.contains("DISARM"),
              let expiry = date(cap.expires_at), expiry > now else { throw AdvisoryError.denied }
        return cap
    }
    static func date(_ value: String) -> Date? {
        let formatter = ISO8601DateFormatter(); formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return formatter.date(from: value) ?? ISO8601DateFormatter().date(from: value)
    }
    static func selection(_ value: WorksetReleaseSelection, capability: WorksetReleaseCapability, now: Date = Date()) throws {
        try validate(try JSONSerialization.jsonObject(with: JSONEncoder().encode(value)), kind: "selection")
        try require(Set(value.subjects.map(\.candidate_id)).count == value.subjects.count)
        guard value.subjects.allSatisfy({ capability.subjects.contains($0) }),
              value.maximum_activations <= min(value.subjects.count, capability.limits.maximum_activations),
              let expiry = date(value.expires_at), let ceiling = date(capability.expires_at),
              expiry > now, expiry <= ceiling else { throw AdvisoryError.denied }
    }
    static func prepared(_ data: Data, access: WorksetReleaseAccess, selection: WorksetReleaseSelection) throws -> WorksetReleasePreview {
        let raw = try object(data); try validate(raw, kind: "prepared")
        let packet = raw["package"] as! [String: Any]
        let preview = try package(packet, access: access, allowBlocked: true)
        try require(preview.selection == selection && raw["package_digest"] as? String == preview.digest)
        try require(try AdvisoryWire.digest(raw["gaps"]!) == AdvisoryWire.digest(packet["gaps"]!))
        let supported = raw["release_supported"] as! Bool
        try require(!supported || preview.gaps.isEmpty)
        return .init(packageData: preview.packageData, digest: preview.digest, selection: preview.selection,
                     members: preview.members, gaps: preview.gaps, supported: supported, worksetID: preview.worksetID)
    }
    static func package(_ raw: [String: Any], access: WorksetReleaseAccess, allowBlocked: Bool = false) throws -> WorksetReleasePreview {
        try validate(raw, kind: "package"); try scope(raw["scope"] as! [String: Any], access: access)
        guard raw["principal_reference"] as? String == access.forgeInstanceID+":"+access.actorID else { throw AdvisoryError.denied }
        let selected = try AdvisoryWire.decode(raw["selection"]!, as: WorksetReleaseSelection.self)
        try require(Set(selected.subjects.map(\.candidate_id)).count == selected.subjects.count)
        let subjects = raw["subjects"] as! [[String: Any]], definition = raw["definition"] as! [String: Any]
        let members = definition["members"] as! [[String: Any]]
        try require(subjects.count == selected.subjects.count && members.count == subjects.count)
        try require(definition["workset_id"] as? String == "released-"+String((raw["release_key"] as! String).dropFirst(7).prefix(40)))
        try require(definition["expires_at"] as? String == selected.expires_at && definition["maximum_activations"] as? Int == selected.maximum_activations)
        try dependencyProofs(subjects, gaps: raw["gaps"] as! [[String: Any]], allowBlocked: allowBlocked)
        try proofs(raw, access: access)
        var rendered: [WorksetReleaseMember] = []
        for index in subjects.indices {
            rendered.append(try member(subjects[index], member: members[index], selected: selected.subjects[index], mode: selected.progression_mode, access: access))
        }
        try semanticKey(raw, members: members, subjects: subjects)
        let gaps = (raw["gaps"] as! [[String: Any]]).map { $0["code"] as! String }
        return .init(packageData: try JSONSerialization.data(withJSONObject: raw), digest: try AdvisoryWire.digest(raw),
                     selection: selected, members: rendered, gaps: gaps, supported: gaps.isEmpty, worksetID: definition["workset_id"] as! String)
    }
    private static func dependencyProofs(_ subjects: [[String: Any]], gaps: [[String: Any]], allowBlocked: Bool) throws {
        var needed: [String] = []
        for (index, subject) in subjects.enumerated() {
            for binding in subject["dependency_bindings"] as! [[String: Any]] {
                let predecessor = subjects.enumerated().first { $0.element["candidate_id"] as? String == binding["candidate_id"] as? String }
                if let code = try dependencyGap(binding, predecessor: predecessor, index: index) {
                    needed.append(code+"|"+(binding["candidate_id"] as! String))
                }
            }
        }
        let codes = ["PREDECESSOR_NOT_SELECTED", "DEPENDENCY_SUBJECT_CHANGED", "DEPENDENCY_ORDER_CONFLICT"]
        let supplied = gaps.filter { codes.contains($0["code"] as! String) }.map {
            ($0["code"] as! String)+"|"+(($0["candidate_id"] as? String) ?? "")
        }
        try require(supplied.sorted() == needed.sorted())
        try require(allowBlocked || gaps.isEmpty)
    }
    private static func dependencyGap(_ binding: [String: Any], predecessor: (offset: Int, element: [String: Any])?, index: Int) throws -> String? {
        guard let predecessor else { return "PREDECESSOR_NOT_SELECTED" }
        let source = predecessor.element["source"] as! [String: Any]
        try require(binding["object_id"] as? String == source["object_id"] as? String)
        if binding["subject_revision"] as? String != predecessor.element["subject_revision"] as? String { return "DEPENDENCY_SUBJECT_CHANGED" }
        return predecessor.offset >= index ? "DEPENDENCY_ORDER_CONFLICT" : nil
    }
    private static func member(_ subject: [String: Any], member: [String: Any], selected: WorksetReleaseSubject, mode: String, access: WorksetReleaseAccess) throws -> WorksetReleaseMember {
        try scope(subject["source"] as! [String: Any], access: access)
        let effectMode = try missionJoin(subject)
        try require(subject["candidate_id"] as? String == selected.candidate_id && subject["subject_revision"] as? String == selected.subject_revision)
        try require(member["candidate_id"] as? String == selected.candidate_id && member["subject_revision"] as? String == selected.subject_revision)
        try require(try AdvisoryWire.digest(member["mission"]!) == AdvisoryWire.digest(subject["mission"]!))
        try require(try canonical(member["planning"]!) == canonical(subject["planning"]!))
        let bindings = subject["dependency_bindings"] as! [[String: Any]], dependencies = member["dependencies"] as! [String]
        let policy = member["progression_policy"] as! [String: Any], planning = subject["planning"] as! [String: Any]
        try require(dependencies == bindings.map { $0["candidate_id"] as! String })
        try require(dependencies == planning["dependencies"] as? [String])
        try require(policy["mode"] as? String == mode && policy["higher_scope_obligations"] as? [String] == planning["human_gates"] as? [String])
        return .init(subject: selected, missionID: subject["mission_id"] as! String,
                     definition: try MissionConceptWire.definition(subject["definition"]!),
                     dependencies: dependencies, humanGates: planning["human_gates"] as! [String],
                     effectMode: effectMode)
    }
    private static func missionJoin(_ subject: [String: Any]) throws -> String {
        let mission = subject["mission"] as! [String: Any], planning = subject["planning"] as! [String: Any]
        let definition = subject["definition"] as! [String: Any]
        try require(try canonical(mission) == planning["mission_spec_digest"] as? String)
        try require(planning["provenance_revision"] as? String == subject["subject_revision"] as? String)
        guard let effect = mission["effect_policy"] as? [String: Any], let mode = effect["mode"] as? String else { throw AdvisoryError.invalid }
        for key in ["effect_policy", "dependencies", "scope", "criterion_assessment_contracts", "maximum_actions", "maximum_consecutive_no_progress_actions", "repository_evidence_source"] {
            try require(try AdvisoryWire.digest([mission[key] ?? NSNull()]) == AdvisoryWire.digest([planning[key] ?? NSNull()]))
        }
        for (key, target) in [("title","title"), ("objective","business_objective"), ("objective","summary"), ("business_value","business_value"), ("acceptance_criteria","acceptance_criteria"), ("risks","risks"), ("dependencies","dependencies")] {
            try require(try AdvisoryWire.digest([definition[key]!]) == AdvisoryWire.digest([mission[target]!]))
        }
        try require(try AdvisoryWire.digest(definition["exclusions"]!) == AdvisoryWire.digest(planning["non_goals"]!))
        let constraints = mission["engineering_constraints"] as! [String]
        let required = ["EXPECTED RESULT: "+(definition["expected_result"] as! String)] +
            (definition["scope"] as! [String]).map { "IN SCOPE: "+$0 } +
            (definition["exclusions"] as! [String]).map { "EXCLUDED: "+$0 } + (definition["architecture_choices"] as! [String])
        try require(required.allSatisfy { constraints.contains($0) })
        return mode
    }
    private static func semanticKey(_ raw: [String: Any], members: [[String: Any]], subjects: [[String: Any]]) throws {
        var semantic = raw["scope"] as! [String: Any]
        for key in ["principal_reference", "selection", "operator_binding"] { semantic[key] = raw[key] }
        semantic["members"] = members
        semantic["candidate_decisions"] = subjects.map { subject in
            let decisions = subject["candidate_decisions"] as! [String: [String: Any]]
            return ["business": decisions["business"]!["canonical_decision_digest"]!,
                    "architecture": decisions["architecture"]!["canonical_decision_digest"]!]
        }
        try require(try AdvisoryWire.digest(semantic) == raw["release_key"] as? String)
    }
}

extension WorksetReleaseWire {
    static func operation(_ data: Data, access: WorksetReleaseAccess, expected: WorksetReleaseCommand) throws -> WorksetReleaseObservation {
        let raw = try object(data); try validate(raw, kind: "operation")
        let preview = try package(raw["frozen_package"] as! [String: Any], access: access)
        let request = try AdvisoryWire.decode(raw["original_request"]!, as: WorksetReleaseCommand.self)
        try require(request == expected && raw["operation_id"] as? String == expected.operation_id)
        try require(request.selection == preview.selection && request.package_digest == preview.digest)
        try require(raw["package_digest"] as? String == preview.digest && raw["workset_id"] as? String == preview.worksetID)
        let state = raw["state"] as! String
        let receipt = raw["original_receipt"] as? [String: Any], current = raw["current"] as? [String: Any]
        try require(state == "PENDING" ? receipt == nil : receipt != nil && current != nil)
        if let receipt { try checkedReceipt(receipt, preview: preview, expected: expected, access: access) }
        let currentData = try current.map { try JSONSerialization.data(withJSONObject: $0) }
        let snapshot = try currentData.map { try WorklistProjection.decode($0, scope: .init(instanceID: access.forgeInstanceID, actorID: access.actorID, worksetID: preview.worksetID)) }
        if let snapshot {
            let packet = raw["frozen_package"] as! [String: Any], signer = packet["operator_binding"] as! [String: Any]
            try require(snapshot.installationID == signer["installation_id"] as? String)
            if let receipt { try require(snapshot.worksetRevision >= (receipt["applied_revision"] as! Int)) }
            try require(zip(snapshot.items, preview.members).allSatisfy { item, member in item.missionID == nil || item.missionID == member.missionID })
            for (index, pair) in zip(snapshot.items, preview.members).enumerated() {
                try require(pair.0.committedPosition == index)
                if pair.0.executionState != "UNAVAILABLE" { try require(pair.0.dependencies == pair.1.dependencies) }
            }
            try require(snapshot.items.map(\.subjectID) == preview.members.map(\.id))
            try require(snapshot.items.map(\.subjectRevision) == preview.members.map { $0.subject.subject_revision })
            let definition = (raw["frozen_package"] as! [String: Any])["definition"]!
            try require(snapshot.membershipRevision == canonical(definition))
        }
        return .init(data: data, operationID: expected.operation_id, state: state, preview: preview,
                     originalReceiptData: try receipt.map { try JSONSerialization.data(withJSONObject: $0) },
                     currentData: currentData, currentRevision: snapshot?.worksetRevision, snapshot: snapshot)
    }
    private static func canonical(_ value: Any) throws -> String {
        let data = try CanonicalJSON.data(value, ascii: false)
        return "sha256:"+SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
    private static func checkedReceipt(_ receipt: [String: Any], preview: WorksetReleasePreview, expected: WorksetReleaseCommand, access: WorksetReleaseAccess) throws {
        let packet = try object(preview.packageData)
        try require(receipt["intent"] as? String == expected.intent && receipt["package_digest"] as? String == preview.digest)
        try require(receipt["principal_reference"] as? String == access.forgeInstanceID+":"+access.actorID)
        try require(receipt["definition_digest"] as? String == canonical(packet["definition"]!))
        try require(receipt["workset_id"] as? String == preview.worksetID)
        try require(receipt["candidate_mission_ids"] as? [String] == preview.members.map(\.missionID))
        try require(receipt["original_release"] as? String == (expected.intent == "release" ? "AUTO_WHEN_ELIGIBLE" : "DISARMED"))
        // A producer's canonical receipt may belong to an earlier alias; the exact original request above binds this operation.
    }
}

extension WorksetReleaseWire {
    private static func proofs(_ packet: [String: Any], access: WorksetReleaseAccess) throws {
        let signer = packet["operator_binding"] as! [String: Any]
        for subject in packet["subjects"] as! [[String: Any]] {
            let decisions = subject["candidate_decisions"] as! [String: [String: Any]]
            try require(decisions["business"]!["decision_id"] as? String != decisions["architecture"]!["decision_id"] as? String)
            for (key, kind) in [("business", "BUSINESS"), ("architecture", "ARCHITECTURE")] {
                let receipt = decisions[key]!
                try require(receipt["kind"] as? String == kind && receipt["candidate_id"] as? String == subject["candidate_id"] as? String)
                try require(receipt["subject_revision"] as? String == subject["subject_revision"] as? String)
                try require(receipt["principal_reference"] as? String == access.forgeInstanceID+":"+access.actorID)
                for key in ["installation_id", "operator_id", "operator_binding_version"] {
                    try require(try AdvisoryWire.digest([receipt[key]!]) == AdvisoryWire.digest([signer[key]!]))
                }
                try require(try AdvisoryWire.digest(receipt["canonical_decision"]!) == receipt["canonical_decision_digest"] as? String)
                try require(try canonical(receipt["lifecycle_evidence"]!) == receipt["lifecycle_evidence_digest"] as? String)
                try decisionJoin(receipt, subject: subject, kind: kind, signer: signer)
            }
        }
    }
    private static func decisionJoin(_ receipt: [String: Any], subject: [String: Any], kind: String, signer: [String: Any]) throws {
        let canonical = receipt["canonical_decision"] as! [String: Any], evidence = receipt["lifecycle_evidence"] as! [String: Any]
        try require(canonical["decision_id"] as? String == receipt["decision_id"] as? String)
        try require(canonical["subject_id"] as? String == subject["candidate_id"] as? String && canonical["subject_revision"] as? String == subject["subject_revision"] as? String)
        try require(canonical["capability"] as? String == kind+"_APPROVAL" && canonical["decision"] as? String == "approved")
        try require(canonical["installation_id"] as? String == signer["installation_id"] as? String && canonical["operator_id"] as? String == signer["operator_id"] as? String)
        try require(evidence["actor"] as? String == "primary_operator" && evidence["kind"] as? String == kind.lowercased()+"_decision")
        try require(evidence["occurred_at"] as? String == receipt["admitted_at"] as? String && evidence["rationale"] as? String == receipt["rationale"] as? String)
        try require(Set([subject["candidate_id"] as! String, subject["subject_revision"] as! String, receipt["decision_id"] as! String]).isSubset(of: Set(evidence["references"] as! [String])))
        let planning = subject["planning"] as! [String: Any]
        try require((canonical["gates"] as! [String]).sorted() == (planning["human_gates"] as! [String]).sorted())
        if kind == "ARCHITECTURE" {
            try require(try AdvisoryWire.digest(planning) == (canonical["evidence"] as! [String: Any])["planning_digest"] as? String)
        }
    }
}
